public static boolean areAnagrams(String a,String b)
{

    // Your code here
    if(a.length() != b.length()){
        return false;
    }

    char[] arr1 = a.toCharArray();
    char[] arr2 = b.toCharArray();
    Arrays.sort(arr1);
    Arrays.sort(arr2);
    for(int i=0;i<arr1.length;i++){
        if(arr1[i] != arr2[i]){
            return false;
        }
    }
    return true;

}
